    q=collections.deque()
    for i in range(H):
        for j in (0,W-1):
            if gi[i][j]==bg: q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if gi[i][j]==bg and (i,j) not in q: q.append((i,j))
    seen=set()
    while q:
        i,j=q.popleft()
        if (i,j) in seen: continue
        seen.add((i,j))
        for ni,nj in [(i+1,j),(i-1,j),(i,j+1),(i,j-1)]:
            if 0<=ni<H and 0<=nj<W and gi[ni][nj]==bg and (ni,nj) not in seen and (ni,nj) not in q:
                q.append((ni,nj))
    return {(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg} - seen
