G=load()
def analyze(name):
    gi=G[name+' input']; oo=G[name+' output']
    H,W=len(gi),len(gi[0])
    cnt=collections.Counter(c for r in gi for c in r); bg=max(cnt,key=lambda c:cnt[c]); ob=[c for c,k in cnt.items() if c!=bg][0]
    st={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]==bg}
    ch={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]!=bg}
    # distances to nearest marker via bg (4-conn bfs)
    dist=collections.defaultdict(lambda:10**9); q=collections.deque()
    for i in range(H):
        for j in range(W):
            if gi[i][j]==ob: dist[(i,j)]=0; q.append((i,j))
    while q:
        a,b=q.popleft()
        for ni,nj in [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]:
            if 0<=ni<H and 0<=nj<W and gi[ni][nj]==bg and dist[(ni,nj)]==10**9:
                dist[(ni,nj)]=dist[(a,b)]+1; q.append((ni,nj))
    tab=collections.defaultdict(Counter)
    for i in range(H):
        for j in range(W):
            if gi[i][j]==bg: tab[min(dist[(i,j)],H)].update([st.__contains__((i,j)),ch.__contains__((i,j))])
    print('demo',name)
    for k,v in sorted(tab.items()): print('  dist%d: stay=%d changed=%d'%(k,v[0],v[1]))
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']: analyze(n)

