def rayhit(gi,i,j,di,dj):
    H_,W_=len(gi),len(gi[0]); k=1
    while 0<=i+di*k<H_ and 0<=j+dj*k<W_ and gi[i+di*k][j+dj*k]==bg: k+=1
    return gi[i+di*k][j+dj*k]==ob
def rule_cells(gi,do_change_if):
    H_,W_=len(gi),len(gi[0])
    cnt=collections.Counter(c for r in gi for c in r); bg=max(cnt,key=lambda c:cnt[c]); ob=[c for c,k in cnt.items() if c!=bg][0]
    out=[r[:] for r in gi]
    for i in range(H_):
        for j in range(W_):
            if gi[i][j]!=bg: continue
            cond = do_change_if(i,j,gi,ob,bg)
            out[i][j]=3 if cond else out[i][j]
    return out
