G=load()
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    gi=G[n+' input']; oo=G[n+' output']
    H,W=len(gi),len(gi[0])
    cnt=collections.Counter(c for r in gi for c in r); bg=max(cnt,key=lambda c:cnt[c]); ob=[c for c,k in cnt.items() if c!=bg][0]
    st={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]==bg}
    # BFS reachability of bg from border
    q=collections.deque(); R=set()
    for i in range(H):
        for j in (0,W-1):
            if gi[i][j]==bg: q.append((i,j)); R.add((i,j))
    for j in range(W):
        for i in (0,H-1):
            if gi[i][j]==bg and (i,j) not in R: q.append((i,j)); R.add((i,j))
    while q:
        a,b=q.popleft()
        for ni,nj in [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]:
            if 0<=ni<H and 0<=nj<W and gi[ni][nj]==bg and (ni,nj) not in R:
                R.add((ni,nj)); q.append((ni,nj))
    ch={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]!=bg}
    print(n,'stays==reach:',st==R, 'changes==unreach:',ch=={p for p in set(st)|ch if p not in R})

def stats(n):
    gi=G[n+' input']; oo=G[n+' output']
    H,W=len(gi),len(gi[0])
    cnt=collections.Counter(c for r in gi for c in r); bg=max(cnt,key=lambda c:cnt[c]); ob=[c for c,k in cnt.items() if c!=bg][0]
    st={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]==bg}
    ch={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and oo[i][j]!=bg}
    return gi,oo,H,W,bg,ob,st,ch
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    gi,oo,H,W,bg,ob,st,ch=stats(n)
    # characterize stayed cells: rows they occupy - are they in long runs between markers?
    print('==',n,'stay n=',len(st),'change n=',len(ch))
    rowruns=collections.defaultdict(list)
    for i in range(H):
        j=0
        while j<W:
            if gi[i][j]==bg:
                j0=j
                while j<W and gi[i][j]==bg: j+=1
                run=(j0,min(j-1,j-1)); rowruns[i].append((j0,j))
            else: j+=1
    for i in range(H):
        runs=rowruns.get(i,[])
        same_row_st=sum(1 for s in runs if any(s[0]<=p<s[1] for p,q in st))
        same_row_ch=sum(1 for s in runs if any(s[0]<=p<s[1] for p,q in ch))
    print(' per-row changes:',[(i,sum(1 for s in [] ) ) for i in range(H)][:10])
    print(sorted(rowruns)[0], rowruns[sorted(rowruns)[0]])

